package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class QueryVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property query of observed panel ")
  void test_query_v_o_builder() {
    Assertions.assertFalse(QueryVO.nullValue().getQuery().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(QueryVO.tryFrom(null).getQuery().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", QueryVO.from("one").getQuery().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> QueryVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", QueryVO.from("one").toString());
  }
}
